INSERT INTO product (slug, name, category, short_description, description, price_cents, stock, emoji, color) VALUES
  ('espresso-classico', 'Espresso Classico', 'Kaffee', 'Kräftiger Espresso mit Noten von Zartbitterschokolade und Haselnuss.', 'Unsere Hausmischung aus 70 % Arabica und 30 % Robusta, langsam im Trommelröster geröstet. Ideal für Siebträger und Vollautomat. 250 g ganze Bohnen.', 890, 40, '☕', '#6b3e26'),
  ('cafe-creme-mild', 'Café Crème Mild', 'Kaffee', 'Sanfter, ausgewogener Kaffee für jeden Tag.', 'Helle Röstung mit wenig Säure und einem weichen Körper. Passt zu Filter, French Press und Vollautomat. 250 g ganze Bohnen.', 790, 55, '☕', '#a0673f'),
  ('aethiopien-yirgacheffe', 'Äthiopien Yirgacheffe', 'Kaffee', 'Single Origin mit floralen Noten und Zitrus.', 'Gewaschener Arabica aus der Region Yirgacheffe, angebaut auf 1.900 m Höhe. Helle Röstung, perfekt für den Handfilter. 250 g ganze Bohnen.', 1190, 18, '☕', '#c08552'),
  ('kolumbien-huila', 'Kolumbien Huila', 'Kaffee', 'Karamell, rote Äpfel und eine feine Süße.', 'Arabica aus kleinbäuerlichem Anbau in Huila. Mittlere Röstung, vielseitig für Filter und Espresso. 250 g ganze Bohnen.', 1090, 25, '☕', '#8c5a3c'),
  ('entkoffeiniert-swiss-water', 'Entkoffeiniert Swiss Water', 'Kaffee', 'Voller Geschmack, ohne Koffein, schonend entkoffeiniert.', 'Mit dem chemiefreien Swiss-Water-Verfahren entkoffeiniert. Schokoladig und rund, auch spät am Abend. 250 g ganze Bohnen.', 950, 30, '☕', '#7a5230'),
  ('cold-brew-blend', 'Cold Brew Blend', 'Kaffee', 'Grob gemahlen für kalt aufgegossenen Kaffee.', 'Eine Mischung, die kalt extrahiert besonders süß und mild schmeckt. Bereits grob gemahlen, einfach mit Wasser ansetzen. 250 g.', 990, 22, '🧊', '#4f6d7a'),
  ('earl-grey-bio', 'Earl Grey Bio', 'Tee', 'Schwarzer Tee mit Bergamotte aus kontrolliert biologischem Anbau.', 'Kräftiger Ceylon-Schwarztee, aromatisiert mit natürlichem Bergamotteöl. 100 g loser Tee.', 650, 35, '🫖', '#3d5a40'),
  ('sencha-japan', 'Grüner Tee Sencha', 'Tee', 'Frischer, grasiger Grüntee aus Japan.', 'Gedämpfter Sencha aus der Präfektur Shizuoka. Mit 70–80 °C heißem Wasser aufgießen. 100 g loser Tee.', 720, 28, '🍵', '#6a8d4f'),
  ('kraeutertee-sommerwiese', 'Kräutertee Sommerwiese', 'Tee', 'Pfefferminze, Zitronenmelisse und Kamille.', 'Koffeinfreie Kräutermischung für den Abend. 80 g lose Kräuter.', 590, 40, '🌿', '#7fa36b'),
  ('handfilter-keramik', 'Handfilter aus Keramik', 'Zubehör', 'Für 1–2 Tassen, passend für Filtergröße 2.', 'Handgefertigter Porzellan-Handfilter, der die Wärme hält und eine gleichmäßige Extraktion ermöglicht. Spülmaschinenfest.', 2490, 12, '🫗', '#d9cbb7'),
  ('milchkaennchen', 'Milchkännchen 350 ml', 'Zubehör', 'Edelstahl-Kännchen für Milchschaum und Latte Art.', 'Aus gebürstetem Edelstahl mit präziser Ausgießtülle. Ideal für Cappuccino und Flat White.', 1990, 20, '🥛', '#9aa5ad'),
  ('handmuehle-pro', 'Handmühle Pro', 'Zubehör', 'Kegelmahlwerk aus Edelstahl, 40 Mahlstufen.', 'Präzise Handmühle für Espresso bis French Press. Wenige Stück auf Lager.', 4900, 3, '⚙️', '#55606a'),
  ('geschenkset-entdecker', 'Geschenkset Entdecker', 'Zubehör', 'Drei Single Origins à 100 g in einer schönen Box.', 'Äthiopien, Kolumbien und Brasilien zum Probieren, verpackt in einer Geschenkbox mit Verkostungskarte.', 3490, 15, '🎁', '#b5654a');
